contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint am, uint dep) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (dep)); require(dep <= 1000000000000000000000000000000);
        require(address(this).balance >= dep);
        require(dep >= am);
        c.SetMinSum(am); if (__ESBMC_reverted()) return;
        c.Deposit{value: dep}(); if (__ESBMC_reverted()) return;
        uint balBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint cBalBefore = address(c).balance;
        bool reverted;
        c.Collect(am); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        uint balAfter = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint cBalAfter = address(c).balance;
        assert(reverted ? (balAfter == balBefore && cBalAfter == cBalBefore) : (balAfter == balBefore - am && cBalAfter == cBalBefore - am));
    }

    receive() external payable {}
}

