pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    BANK_SAFE c;

    function setUp() public {
        c = new BANK_SAFE();
    }

    function _run(uint256 am, uint256 dep) internal {
        dep = bound(dep, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= dep);
        vm.assume(dep >= am);
        try c.SetMinSum(am) {} catch { return; }
        try c.Deposit{value: dep}() {} catch { return; }
        uint256 balBefore;
        try c.balances(address(this)) returns (uint256 __r) { balBefore = __r; } catch { return; }
        uint cBalBefore = address(c).balance;
        bool reverted;
        try c.Collect(am) { reverted = false; } catch { reverted = true; }
        uint256 balAfter;
        try c.balances(address(this)) returns (uint256 __r) { balAfter = __r; } catch { return; }
        uint cBalAfter = address(c).balance;
        assertTrue(reverted ? (balAfter == balBefore && cBalAfter == cBalBefore) : (balAfter == balBefore - am && cBalAfter == cBalBefore - am));
    }

    function testFuzz_run(uint256 am, uint256 dep) public {
        _run(am, dep);
    }

    receive() external payable {}
}
